import {childArt} from './word-art.js';
import {finishIllustration,groundShadow} from './illustration-style.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const at=(x,y,body,attrs='')=>'<g transform="translate('+x+' '+y+')" '+attrs+'>'+body+'</g>';
const flower=(color='#f57c8d')=>'<g data-object="flower"><path d="M0 5V65m0-25q-27-20-28-1 15 15 28 7m0-18q27-20 28-1-15 15-28 7" fill="#59b77c" stroke="#2f8855" stroke-width="4"/>'+[0,60,120,180,240,300].map(a=>'<ellipse cx="0" cy="-24" rx="15" ry="24" fill="'+color+'" stroke="#b0645f" stroke-width="1.5" transform="rotate('+a+')"/>').join('')+'<circle r="16" fill="#ffe48a" stroke="#b98539" stroke-width="2"/></g>';
const bird=()=>'<g data-object="bird"><ellipse cx="0" cy="4" rx="31" ry="24" fill="#65bdd7" stroke="#337386" stroke-width="2"/><circle cx="18" cy="-15" r="20" fill="#8bd8e7" stroke="#337386" stroke-width="2"/><path d="m35-18 22 10-22 5" fill="#f5bc55"/><circle cx="23" cy="-20" r="3.5" fill="#273c56"/><path d="m-7 0-18 10 28 9" fill="#3989b3"/><path d="m-19 8-23 13 13-24" fill="#4d9cbf"/><path d="m-5 27-2 10m18-10 2 10" stroke="#a5743b" stroke-width="3"/></g>';
const apple=()=>'<g data-object="apple"><path d="M0-23q-33-17-35 17 2 36 34 37 34-1 36-37-2-34-35-17" fill="#f0766f" stroke="#ab494a" stroke-width="2"/><path d="M0-23q-1-15 7-22" stroke="#77553a" stroke-width="5" fill="none"/><path d="M5-28q24-24 31-7-12 15-31 7" fill="#55a679"/><path d="M-22-9q-7 14 3 25" fill="none" stroke="#ffc8ac" stroke-width="5" stroke-linecap="round"/></g>';
const basket=()=>'<g data-object="basket"><path d="M-65-18q5-100 130 0" fill="none" stroke="#946b47" stroke-width="12"/><path d="M-75-15H75L56 80H-56Z" fill="#eab56a" stroke="#96673e" stroke-width="3"/><path d="M-70 0H70m-66 22h124m-121 22H60m-115 22H55M-45-14l9 92m24-92 3 92m24-92-3 92m35-92-9 92" stroke="#bd874b" stroke-width="3"/></g>';
const piece=()=>'<path data-object="piece" d="M0 0 0-42A42 42 0 0 1 36.373 21Z" fill="#ffcf82" stroke="#b87858" stroke-width="2"/><path d="M0 0 0-35A35 35 0 0 1 30.311 17.5Z" fill="#f997ad"/><circle cx="12" cy="-17" r="4" fill="#cc5478"/>';
const boy=color=>'<g data-object="brother" transform="translate(-65 -45) scale(1.3)">'+childArt('hold',color)+'</g>';
const star=()=>'<path data-object="sticker" d="M0-26 8-9 27-7 13 7 17 26 0 16-17 26-13 7-27-7-8-9Z" fill="#ffd35e" stroke="#c09231" stroke-width="2"/>';
const coin=n=>'<g data-object="taka"><circle r="38" fill="#ffda76" stroke="#b88835" stroke-width="3"/><circle r="29" fill="none" stroke="#d3a14c" stroke-width="2"/><text y="10" text-anchor="middle" fill="#614723" font-size="28" font-weight="bold">৳'+n+'</text></g>';
const mango=()=>'<g data-object="mango"><path d="M-28-46q66-17 63 47-2 63-54 66-56-2-48-53 5-35 39-60" fill="#ffce61" stroke="#b38639" stroke-width="3"/><path d="M-4-46q-6-22 12-31" fill="none" stroke="#6b8c48" stroke-width="5"/><path d="M4-57q41-33 51-10-23 21-51 10" fill="#70b57b"/></g>';
const banana=()=>'<g data-object="banana"><path d="M-55-40q15 76 105 42-42 86-105 18-22-29 0-60Z" fill="#ffe585" stroke="#aa853b" stroke-width="3"/><path d="M-55-40q17 91 105 42" fill="none" stroke="#d8b247" stroke-width="5"/><path d="m-55-40-4-9 10-2 6 11m88 40 7-7 7 6-9 11" fill="#8b7052"/></g>';
const tree=()=>'<g data-object="tree"><path d="M275 307v-170h52v170m-31-104-74-47m90 55 75-53" fill="#b18052" stroke="#8d6244" stroke-width="14" stroke-linejoin="round"/><path d="M192 81q-46 27-16 70-48 41 17 71 46 32 101-2 49 40 109 4 64-29 25-75 28-41-29-60-22-45-69-22-68-35-96 14Z" fill="#9dd77d" stroke="#559457" stroke-width="4"/><path d="M176 168q113 36 240-7" stroke="#8d6244" stroke-width="9" fill="none" stroke-linecap="round"/></g>';
const bg=()=>'<rect width="600" height="360" rx="26" fill="#e8f7fc"/><path d="M0 291q150-27 300 0 150-27 300 0v69H0Z" fill="#d9ecc1"/><circle cx="545" cy="48" r="25" fill="#ffdb75"/>';
const countRow=(n,draw,y=168,color)=>Array.from({length:n},(_,i)=>at(300+(i-(n-1)/2)*Math.min(96,480/Math.max(1,n-1)),y,draw(color))).join('');
function clock(hour=3,minute=0,moving=false){return '<g data-clock-hour="'+hour+'" data-clock-minute="'+minute+'"><circle cx="300" cy="180" r="141" fill="#fffdf4" stroke="#6d91c1" stroke-width="10"/>'+Array.from({length:12},(_,i)=>{const n=i+1,a=n*Math.PI/6;return '<text x="'+(300+112*Math.sin(a))+'" y="'+(188-112*Math.cos(a))+'" text-anchor="middle" fill="#2c4668" font-size="25" font-weight="bold">'+n+'</text>';}).join('')+'<g transform="rotate('+(hour*30+minute/2)+' 300 180)"><path '+(moving?'data-motion="clock" data-from="rotate(-90deg)" data-to="rotate(0deg)" ':'')+' d="M300 180V111" stroke="#345ea0" stroke-width="11" stroke-linecap="round"/></g><path d="M300 180V83" transform="rotate('+(minute*6)+' 300 180)" stroke="#d78062" stroke-width="7" stroke-linecap="round"/><circle cx="300" cy="180" r="9" fill="#344c6b"/></g>';}
function cup(x,amount,color='#5c9bc7',motion=false){const height=amount*178;return at(x,80,'<g data-object="cup" data-water="'+amount+'"><path d="M-58 0H58L45 185H-45Z" fill="#ffffffb8" stroke="'+color+'" stroke-width="5"/><g '+(motion?'data-motion="water" data-from="scaleY(0)" data-to="scaleY(1)" ':'')+'><path data-object="water" d="M-43 178H43L'+(43+(height/178)*11)+' '+(178-height)+'H'+(-43-(height/178)*11)+'Z" fill="#6bc3e6" stroke="#3786b5" stroke-width="2"/></g><path d="M-58 0H58" stroke="'+color+'" stroke-width="5"/><path d="M-43 21-35 93" stroke="white" stroke-width="5" stroke-linecap="round"/></g>');}
const shape=(kind)=>kind==='circle'?'<circle data-shape="circle" r="68" fill="#ffcd72" stroke="#aa7c30" stroke-width="4"/>':kind==='square'?'<rect data-shape="square" x="-68" y="-68" width="136" height="136" fill="#85c8ec" stroke="#4778a2" stroke-width="4"/>':kind==='rectangle'?'<rect data-shape="rectangle" x="-95" y="-55" width="190" height="110" fill="#99d2b0" stroke="#44845f" stroke-width="4"/>':'<path data-shape="triangle" d="M0-78 80 62H-80Z" fill="#dfb5eb" stroke="#876596" stroke-width="4"/>';
function content(name){
 const choice=name.match(/^(flower|bird|apple|piece|sticker|taka)-choice-(\d+)$/);if(choice){const n=Number(choice[2]),draw={flower,bird,apple,piece,sticker:star,taka:()=>coin(n)}[choice[1]];return choice[1]==='taka'?at(300,185,coin(n)):(n<=3?countRow(n,draw):Array.from({length:n},(_,i)=>at(165+(i%3)*135,110+Math.floor(i/3)*145,draw())).join(''));}
 if(name==='flower-one')return countRow(1,flower);if(name==='flower-two'||name==='red-two')return countRow(2,flower,168);if(name==='flower-three'||name==='yellow-three')return countRow(3,flower,168,name==='yellow-three'?'#ffd85e':undefined);
 if(name==='flowers-five'||name==='flowers-join')return at(0,0,countRow(2,flower,130),name==='flowers-join'?'data-motion="join" data-from="translate(-65px, -35px)" data-to="translate(0px, 0px)"':'')+at(0,0,countRow(3,flower,235,'#ffd85e'),name==='flowers-join'?'data-motion="join" data-from="translate(65px, 35px)" data-to="translate(0px, 0px)"':'');
 if(name==='bird-one')return at(300,180,bird());if(name==='tree')return tree();if(name.startsWith('tree-')||name==='bird-away'){const n={'tree-one':1,'tree-two':2,'tree-three':3,'bird-away':2}[name];return tree()+Array.from({length:n},(_,i)=>at(n===1?300:[226,363,298][i],i===2?100:155,bird())).join('')+(name==='bird-away'?at(298,100,'<g data-motion="fly" data-from="translate(0px, 0px)" data-to="translate(270px, -130px)" data-fade="true">'+bird()+'</g>'):'');}
 if(name==='cake-piece')return at(300,195,piece());
 if(['cake-whole','cake-cut'].includes(name))return '<circle data-object="cake" cx="300" cy="180" r="92" fill="#ffcf82" stroke="#b87858" stroke-width="4"/><circle cx="300" cy="180" r="82" fill="#f997ad"/>'+[0,120,240].map(a=>at(300,180,'<g transform="rotate('+a+')"><circle cx="0" cy="-55" r="8" fill="#c55173"/></g>')).join('')+(name==='cake-cut'?'<path d="M300 180V88m0 92 79.674 46m-79.674-46-79.674 46" stroke="#916345" stroke-width="5" stroke-dasharray="7 6"/>':'');
 if(['brothers','cake-share','cake-shared'].includes(name))return [120,300,480].map((x,i)=>at(x,145,boy(['#82c6db','#edac7d','#a8bd7e'][i]))).join('')+(name==='brothers'?'':[120,300,480].map((x,i)=>at(x,282,'<ellipse rx="66" ry="42" fill="#fffaf2" stroke="#87a5bd" stroke-width="3"/>'+at(0,9,piece(),name==='cake-share'?'data-motion="share" data-from="translate('+(300-x)+'px,-237px) rotate('+(i*120)+'deg)" data-to="translate(0px,0px) rotate(0deg)"':''))).join(''));
 if(name==='apple'||name==='apples-two')return countRow(name==='apple'?1:2,apple,190);if(name==='basket')return at(300,180,basket());if(name==='baskets')return [100,300,500].map(x=>at(x,175,basket()+at(-34,-40,apple())+at(34,-40,apple()))).join('');
 if(['circle','square','triangle','rectangle','triangle-sides','triangle-corners'].includes(name)){const kind=name.split('-')[0],familiar={circle:'<ellipse cx="470" cy="190" rx="58" ry="38" fill="#fffdf6" stroke="#cd9c51" stroke-width="5"/>',square:'<rect x="405" y="125" width="110" height="110" rx="4" fill="#e4f5ff" stroke="#779fb6" stroke-width="7"/><path d="M460 125v110m-55-55h110" stroke="#779fb6" stroke-width="5"/>',triangle:'<path d="M448 240V85l88 70-88 1" fill="#e5bce7" stroke="#816b9a" stroke-width="5"/>',rectangle:'<rect x="424" y="89" width="88" height="179" rx="5" fill="#bbdab5" stroke="#638667" stroke-width="5"/><circle cx="492" cy="190" r="4" fill="#7f7154"/>'}[kind];return at(220,175,shape(kind))+familiar+(name==='triangle-sides'?'<g stroke="#4579b6" stroke-width="8"><path d="M220 97 300 237m0 0H140m0 0 80-140"/></g>'+[[280,166],[220,270],[147,168]].map(([x,y],i)=>'<text x="'+x+'" y="'+y+'" font-size="26" font-weight="bold" fill="#2b4775">'+(i+1)+'</text>').join(''):name==='triangle-corners'?[[220,97],[300,237],[140,237]].map(([x,y])=>'<circle cx="'+x+'" cy="'+y+'" r="11" fill="#ffd46d" stroke="#906127" stroke-width="3"/>').join(''):'');}
 if(name==='shapes')return at(108,180,shape('circle'))+at(300,180,shape('triangle'))+at(492,180,shape('square'));
 if(['ribbon-blue','ribbon-red','ribbons','ruler'].includes(name)){const both=name==='ribbons',red=name==='ribbon-red';return '<path d="M95 65v215" stroke="#8497b1" stroke-width="3" stroke-dasharray="6 5"/>'+(!red?'<rect data-object="ribbon" data-length="6" x="95" y="105" width="330" height="38" rx="6" fill="#6aaed7" stroke="#397aa9" stroke-width="3"/>':'')+(red||both?'<rect data-object="ribbon" data-length="3" x="95" y="210" width="165" height="38" rx="6" fill="#ee9293" stroke="#b85c66" stroke-width="3"/>':'')+(name==='ruler'?'<rect x="95" y="160" width="350" height="60" rx="4" fill="#ffe398" stroke="#b68b42" stroke-width="2"/>'+Array.from({length:7},(_,i)=>'<path d="M'+(95+i*55)+' 160v16" stroke="#5d533d" stroke-width="2"/><text x="'+(95+i*55)+'" y="202" text-anchor="middle" font-size="22" fill="#5d533d">'+i+'</text>').join(''):'');}
 if(name==='cup-empty')return cup(300,0);if(name==='cup-full'||name==='cup-fill')return cup(300,1,'#5c9bc7',name==='cup-fill')+(name==='cup-fill'?'<g data-motion="pour" data-from="translate(0px,0px)" data-to="translate(0px,0px)" data-fade="true" ><path d="M280 26q21 0 20 54" stroke="#6bc3e6" stroke-width="12" fill="none"/><path d="m265 18 28-7 14 18-33 9Z" fill="#99c8e5" stroke="#477c9e" stroke-width="3"/></g>':'');if(name==='cups')return cup(180,.8)+cup(420,.25,'#d99765')+'<text x="180" y="306" text-anchor="middle" font-size="25" fill="#346589">A</text><text x="420" y="306" text-anchor="middle" font-size="25" fill="#98603d">B</text>';if(name==='cup-more')return cup(300,.8);if(name==='cup-less')return cup(300,.25,'#d99765');
 if(name==='mango')return at(300,180,mango());if(name==='banana')return at(300,180,banana());if(name==='taka-five')return at(300,180,coin(5));if(name==='taka-ten')return at(300,180,coin(10));
 if(name==='shop'||name==='shop-mango'||name==='shop-banana'||name==='shop-total')return (name==='shop-banana'?'':at(name==='shop-mango'?300:185,135,mango())+at(name==='shop-mango'?300:185,268,coin(5)))+(name==='shop-mango'?'':at(name==='shop-banana'?300:420,135,banana())+at(name==='shop-banana'?300:420,268,coin(3)))+(name==='shop-total'?'<text x="300" y="275" text-anchor="middle" font-size="30" fill="#493c5c">+</text><text x="300" y="333" text-anchor="middle" font-size="25" fill="#493c5c">৳5 + ৳3 = ৳8</text>':'');
 if(name==='shop-change')return '<text x="115" y="72" text-anchor="middle" font-size="26" fill="#2c4668">Pay</text>'+at(115,160,coin(10))+'<path d="M178 160h45" stroke="#7b96b3" stroke-width="5"/><path d="m210 151 16 9-16 9" fill="none" stroke="#7b96b3" stroke-width="5"/>'+at(302,160,coin(8))+'<text x="302" y="240" text-anchor="middle" font-size="24" fill="#2c4668">Fruit costs</text>'+at(492,160,coin(2))+'<text x="492" y="240" text-anchor="middle" font-size="24" fill="#2c4668">Change</text><path d="M421 278H178" stroke="#519b81" stroke-width="5"/><path d="m195 269-18 9 18 9" fill="none" stroke="#519b81" stroke-width="5"/>';
 if(name.startsWith('clock-'))return clock(name==='clock-one'?1:name==='clock-six'?6:3,name==='clock-half'?30:0,name==='clock-move');
 if(name==='stickers-three')return countRow(3,star);
 if(name==='chart'||name==='chart-difference')return '<rect x="50" y="57" width="500" height="240" rx="18" fill="#fffdf6" stroke="#9bb5c5" stroke-width="3"/><path d="M170 57v240M50 177h500" stroke="#a6c3d2" stroke-width="3"/>'+at(108,112,bird())+at(108,228,'<g transform="scale(.65)">'+flower()+'</g>')+[230,340,450].map((x,i)=>at(x,112,star(),name==='chart-difference'&&i===2?'data-extra-sticker="true"':'')).join('')+[230,340].map(x=>at(x,238,star())).join('')+(name==='chart-difference'?'<rect x="412" y="70" width="76" height="83" rx="12" fill="none" stroke="#539979" stroke-width="5" stroke-dasharray="6 4"/>':'');
 throw Error('Unknown math scene '+name);
}
export function mathScene(name,small=false){const descriptions={
 'flower-one':'One flower','flower-two':'Two flowers','flower-three':'Three flowers','red-two':'Two red flowers','yellow-three':'Three yellow flowers','flowers-five':'Two red flowers and three yellow flowers: five altogether','flowers-join':'Two red flowers join three yellow flowers: five altogether','bird-one':'One bird','tree':'A tree','tree-one':'One bird sitting on a tree branch','tree-two':'Two birds left on tree branches','tree-three':'Three birds sitting on tree branches','bird-away':'One of three birds flies away, leaving two in the tree','cake-whole':'One round cake','cake-cut':'One cake cut into three equal 120 degree pieces','cake-piece':'One equal piece of cake','brothers':'Three brothers','cake-share':'Three equal pieces are shared, one to each of three brothers','cake-shared':'Three brothers, each with exactly one equal piece on a plate','apple':'An apple','apples-two':'Two apples','basket':'An empty basket','baskets':'Three baskets with two visible apples each: six apples','ribbons':'Ribbons aligned at the same start: blue is twice as long as red','ribbon-blue':'A long blue ribbon','ribbon-red':'A short red ribbon','ruler':'Blue ribbon begins at ruler zero and ends at six','cup-empty':'An empty clear cup','cup-full':'A clear cup filled to the brim','cup-fill':'Water is poured into an empty clear cup until it is full','cups':'Two cups of equal size: blue cup A has more water than orange cup B','cup-more':'Blue cup with a high water level','cup-less':'Orange cup with a low water level','shop':'A mango costs five taka and a banana costs three taka','shop-mango':'A mango costs five taka','shop-banana':'A banana costs three taka','shop-total':'Five plus three equals eight taka','shop-change':'Pay ten taka for fruit costing eight taka and receive two taka change','clock-three':'Three o’clock: short hand at three, long hand at twelve','clock-move':'Clock hands move to three o’clock','clock-one':'One o’clock: short hand at one, long hand at twelve','clock-six':'Six o’clock: short hand at six, long hand at twelve','clock-half':'Half past three: short hand halfway between three and four, long hand at six','chart':'Picture chart: bird row has three stickers; flower row has two','chart-difference':'Matched rows of two stickers and one extra sticker for the bird','stickers-three':'Three stickers','shapes':'A circle, a triangle and a square'};return finishIllustration('<svg class="math-scene '+(small?'math-scene-small':'')+'" viewBox="'+(name.startsWith('clock-')?'140 20 320 320':small&&['circle','square','triangle','rectangle'].includes(name)?'100 65 240 225':small&&name.startsWith('cup-')?'220 50 160 250':'0 0 600 360')+'" role="img" aria-label="'+esc(descriptions[name]||name.replaceAll('-',' '))+'" data-math-scene="'+name+'">'+bg()+content(name)+'</svg>');}
export function animateMathScene(root){const animations=[];if(matchMedia('(prefers-reduced-motion: reduce)').matches)return()=>{};root.querySelectorAll('[data-motion]').forEach(el=>{const keyframes=[{transform:el.dataset.from,opacity:1},{transform:el.dataset.to,opacity:el.dataset.fade?0:1}];const a=el.animate(keyframes,{duration:el.dataset.motion==='fly'?1400:1200,easing:'ease-in-out',fill:'forwards'});animations.push(a);});return()=>animations.forEach(a=>a.cancel());}
export const mathChoice=(c)=>mathScene(c.scene,true)+'<span>'+esc(c.label)+'</span>';
